'use strict';
const DICE_ORIENTATIONS={1:[0,0],2:[0,-90],3:[-90,0],4:[90,0],5:[0,90],6:[0,180]};
class DiceVisual{
 constructor(row){this.row=row;this.motion=matchMedia('(prefers-reduced-motion: reduce)');this.angles=[[0,0],[0,0],[0,0]];this.raf=0;row.innerHTML=Array.from({length:3},(_,i)=>`<div class="die-slot"><canvas class="die-canvas" data-yaw="${[-22,8,25][i]}" role="img"></canvas><span class="die-shadow"></span><span class="die-sparks" aria-hidden="true">${Array.from({length:8},(_,k)=>`<i style="--x:${Math.cos(k*Math.PI/4)*80}px;--y:${Math.sin(k*Math.PI/4)*60-18}px;--r:${k*45}deg"></i>`).join('')}</span></div>`).join('');this.cubes=[...row.querySelectorAll('.die-canvas')];this.shadows=[...row.querySelectorAll('.die-shadow')];new ResizeObserver(()=>this.paint()).observe(row);this.snap([1,3,5]);}
 paint(){this.cubes.forEach((el,i)=>{const p=this.poses?.[i]||{spin:0,tilt:0};drawDice(el,this.angles[i],p);if(this.shadows[i]){this.shadows[i].style.transform=`scale(${1-.22*p.tilt},${1-.12*p.tilt})`;}});}
 snap(values){cancelAnimationFrame(this.raf);this.angles=values.map(v=>[...DICE_ORIENTATIONS[v]]);this.poses=values.map(()=>({spin:0,tilt:0}));this.cubes.forEach((el,i)=>el.setAttribute('aria-label',values[i]+' 点'));this.paint();}
 roll(){cancelAnimationFrame(this.raf);this.row.classList.remove('hit');this.row.classList.add('spinning');this.row.querySelectorAll('.die-slot').forEach(el=>el.classList.remove('impact'));this.cubes.forEach(el=>el.setAttribute('aria-label','单角旋转中'));this.row.setAttribute('aria-label','三颗骰子正在单角旋转');if(this.motion.matches)return;const start=performance.now();this.poses=[0,1,2].map(()=>({spin:0,tilt:0}));const tick=now=>{const t=(now-start)/1000;this.poses=this.poses.map((_,i)=>{const local=Math.max(0,t-i*.055),rise=Math.min(1,local/.19),ease=rise*rise*(3-2*rise);return {tilt:ease,spin:(1180+i*100)*Math.max(0,local-.055)};});this.paint();this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}
 settle(values,done){cancelAnimationFrame(this.raf);this.row.classList.remove('spinning');if(this.motion.matches){this.snap(values);done();return;}const start=performance.now(),base=this.angles.map(a=>[...a]),poses=this.poses.map(p=>({...p})),landed=new Set();const tick=now=>{let complete=true;this.angles=base.map((a,i)=>{const t=Math.min(1,Math.max(0,(now-start-i*85)/520));if(t<1)complete=false;else if(!landed.has(i)){landed.add(i);this.row.querySelectorAll('.die-slot')[i]?.classList.add('impact');this.onLand?.(i);}const slow=1-Math.pow(1-t,3),tip=Math.min(1,Math.max(0,(t-.42)/.58)),ease=tip*tip*(3-2*tip),endSpin=(Math.floor(poses[i].spin/360)+1)*360;this.poses[i]={spin:poses[i].spin+(endSpin-poses[i].spin)*slow,tilt:poses[i].tilt*(1-ease)*(1+.065*Math.sin(t*25)*Math.sin(Math.PI*t))};return a.map((v,j)=>v+(DICE_ORIENTATIONS[values[i]][j]-v)*ease);});this.paint();if(complete){this.snap(values);done();}else this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}
}
// Support height of the rotated cube keeps its lowest corner on the same plane.
function diceSupport(tx,tz,x,y){const rad=a=>a*Math.PI/180,rx=(v,a)=>[v[0],v[1]*Math.cos(rad(a))-v[2]*Math.sin(rad(a)),v[1]*Math.sin(rad(a))+v[2]*Math.cos(rad(a))],ry=(v,a)=>[v[0]*Math.cos(rad(a))+v[2]*Math.sin(rad(a)),v[1],-v[0]*Math.sin(rad(a))+v[2]*Math.cos(rad(a))],rz=(v,a)=>[v[0]*Math.cos(rad(a))-v[1]*Math.sin(rad(a)),v[0]*Math.sin(rad(a))+v[1]*Math.cos(rad(a)),v[2]];return [[1,0,0],[0,1,0],[0,0,1]].reduce((sum,v)=>sum+Math.abs(rx(rz(rx(ry(v,y),x),tz),tx)[1]),0);}
if(typeof module!=='undefined')module.exports={DICE_ORIENTATIONS,diceSupport};
